//! The exponential's and the logarithm's constants, generated by
//! `scripts/exp_ln_constants.py` (mpmath at 256 bits; every double the
//! nearest to its exact value unless said otherwise). Part of the contract:
//! [`exp_core`](crate::semantics::exp_core), [`ln_core`](crate::semantics::ln_core)
//! and every backend's encoding of them read these.
//!
//! `exp`: `x = k ln 2 / N + r` with `|r| <= ln 2 / 2N`, `exp(x) = 2^(k / N)
//! exp(r)`, `2^(j / N)` from a table (the method of Tang, ACM TOMS 15, 1989,
//! as ARM's optimized-routines and glibc take it). Error: below 0.51 ulp,
//! 0.76 ulp for subnormal results (rounded twice).
//!
//! `ln`: `x = 2^k z` with `z` in `[0.6875, 1.375)`, `log x = k ln 2 - log(invc)
//! + log1p(r)` with `r = (z - c) invc` for the `c` of `z`'s subinterval and
//! `invc = 1/c`. Near 1, `c = 1` and `r = z - 1` is exact; elsewhere `|log
//! x| > 2^-6` and the rounding of `r` costs at most 1/8 ulp. Error: below
//! 0.63 ulp.
//!
//! Without a fused multiply-add the same steps round twice; the errors hold
//! for both.

/// `x + MAGIC - MAGIC` rounds `x` (`|x| < 2^51`) to an integer, the low
/// bits of `x + MAGIC` that integer: `1.5 2^52`.
pub const MAGIC: f64 = f64::from_bits(0x4338000000000000);

/// `exp`'s table: `N = 2^7` subintervals.
pub const EXP_TABLE_BITS: u32 = 7;
/// `exp`'s scale is built `2^64` too large, so it stays normal down
/// to the subnormal results, and the result multiplied back once.
pub const EXP_SCALE_BIAS: i64 = 64;
/// `N / ln 2`.
pub const EXP_INV_LN2_N: f64 = f64::from_bits(0x40671547652b82fe);
/// `ln 2 / N` in two parts, the high one of 35 significant bits, so `k
/// EXP_LN2_HI_N` is exact for every `|k| < 2^18` (`|x| < 745.2`).
pub const EXP_LN2_HI_N: f64 = f64::from_bits(0x3f762e42fefc0000);
/// See [`EXP_LN2_HI_N`].
pub const EXP_LN2_LO_N: f64 = f64::from_bits(0xbd3c610ca86c3899);
/// `exp(r) = 1 + r + r^2 (c2 + c3 r + c4 r^2 + c5 r^3)`: interpolation at
/// the Chebyshev nodes of `[-0.00271025, 0.00271025]`, relative error 2^-63.65
/// with the coefficients as doubles.
pub const EXP_POLY: [f64; 4] = [
    f64::from_bits(0x3fdfffffffffff57),
    f64::from_bits(0x3fc5555555555525),
    f64::from_bits(0x3fa55555acf7d28e),
    f64::from_bits(0x3f8111114324c640),
];
